},
{
["key"] = "q:7899:progress:14829",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.5\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.6.0\nquest=7899\nevent=progress\nnpc=14829 Yebb Neblegear\nkind=creature\nmodel=900914\ndisplays=14856\nsex=2\ncreature=Humanoid\ntitle=Small Furry Paws\ntext<<\nThe first lesson in drawing a crowd is: lure them with gadgets and trinkets!  Can you help me?\n\nI need small furry paws to use for prizes.  You can find those on the cats of the Barrens or Darkshore....\n\nBring me some paws and I'll trade you a Darkmoon Faire ticket for them.\n>>\nsum=1082899238\n",
},
{
["key"] = "q:7889:progress:14832",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.5\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.6.0\nquest=7889\nevent=progress\nnpc=14832 Kerri Hicks\nkind=creature\nmodel=1000764\ndisplays=14876\nsex=3\ncreature=Humanoid\ntitle=Coarse Weightstone\ntext<<\nIt takes a lot of work to be the strongest woman alive!  My weight set is getting too light and if I'm too stay fit then I'll need more weights!\n\nDo you think you could bring me some weight stones?  If you do, then I'll give you a Darkmoon Faire ticket.\n>>\nsum=1456014499\n",
},
{
["key"] = "q:7894:progress:14841",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.5\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.6.0\nquest=7894\nevent=progress\nnpc=14841 Rinling\nkind=creature\nmodel=1022938\ndisplays=14877\nsex=2\ncreature=Humanoid\ntitle=Copper Modulator\ntext<<\nYebb is developing a new attraction for the Zoo Bizarre, one that will drive people crazy with wonder, and delight!  But it will take a lot of work, and a lot of materials...\n\nThat includes copper modulators.  We need lots of modulators for the mechanical parts of the attraction.  Bring me copper modulators and I'll trade for them with a Darkmoon Faire ticket.\n>>\nsum=749161218\n",
},
{
["key"] = "q:7895:progress:14841",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.5\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.6.0\nquest=7895\nevent=progress\nnpc=14841 Rinling\nkind=creature\nmodel=1022938\ndisplays=14877\nsex=2\ncreature=Humanoid\ntitle=Whirring Bronze Gizmo\ntext<<\nMy new booth will be a sight to see, yes sir!  A sight to see, and... for a lucky few, to touch!\n\nI can already hear the whirring bronze gizmos singing their song of mechanical rapture as patrons step to my booth and test their skill!\n\nAh... now I need the gizmos themselves to bring my dream closer to fruition.  Please, $N, bring me whirring bronze gizmos... and Darkmoon Faire tickets will be yours!\n>>\nsum=1151684416\n",
},
{
["key"] = "q:7896:progress:14841",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.5\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.6.0\nquest=7896\nevent=progress\nnpc=14841 Rinling\nkind=creature\nmodel=1022938\ndisplays=14877\nsex=2\ncreature=Humanoid\ntitle=Green Fireworks\ntext<<\nWhen I finally get this booth up and running, I'll want to advertise!  And what better way is there to advertise then with fireworks?\n\nWell, some might think that the smell of a cauldron, churning with the boiling heads of your foes is better for drawing crowds, but... we're in mixed company.  So fireworks it will have to be!\n\nBring me green fireworks, $N, and I have a big fistful of Darkmoon Faire tickets for you.\n>>\nsum=531474522\n",
},
