{
["key"] = "q:7902:progress:14829",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.5\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.6.0\nquest=7902\nevent=progress\nnpc=14829 Yebb Neblegear\nkind=creature\nmodel=900914\ndisplays=14856\nsex=2\ncreature=Humanoid\ntitle=Vibrant Plumes\ntext<<\nA person's imagination is an incredible thing.  It can make the smallest hill seem like the largest mountain.  It can make the most innocuous shadow appear cast by a horrible nightmare!\n\nWe at the Darkmoon Faire let our visitor's imaginations blossom!  But to help stretch their imaginations... sometimes we have to get tricky.\n\nI need vibrant plumes for one of my attractions.  You can get them from the birds of the more dangerous areas of Azeroth.  Bring me the plumes and many tickets will be yours!\n>>\nsum=589100066\n",
},
{
["key"] = "q:7813:progress:14729",
["envelope"] = "!SPOKEN1 quests\naddon=SpokenQuests/3.8.5\nbuild=1.60.1/70862\nlocale=enUS\npack=enUS\npackVersion=2.6.0\nquest=7813\nevent=progress\nnpc=14729 Ralston Farnsley\nkind=creature\nmodel=959310\ndisplays=14756\nsex=2\ncreature=Humanoid\ntitle=A Donation of Wool\ntext<<\nWe are currently accepting donations for wool cloth.  A donation of sixty pieces of wool cloth will net you full recognition by the Undercity for your generous actions.  Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.\n>>\nsum=566460240\n",
},
